def pancake_sort(nums):
    def find_max(nums, start, end):
        max_idx = start
        for i in range(start + 1, end + 1):
            if nums[i] > nums[max_idx]:
                max_idx = i
        return max_idx

    def flip(nums, start, end):
        while start < end:
            nums[start], nums[end] = nums[end], nums[start]
            start += 1
            end -= 1

    nums = nums.copy()
    n = len(nums)

    for i in range(n, 1, -1):
        max_idx = find_max(nums, 0, i - 1)
        if max_idx != i - 1:
            flip(nums, max_idx, 0)
            flip(nums, i - 1, 0)

    return nums
